mapper.select:
SELECT
m.project_id,p.project_name,m.create_by,u.nick_name,i.indicator_id,n.indicator_name,m.category_id,i.category_name,m.organization_id,COUNT(*)
AS marking_num
FROM tb_marking m
LEFT JOIN tb_pathological_indicator_category i ON m.category_id = i.category_id
LEFT JOIN tb_pathological_indicator n ON n.indicator_id = i.indicator_id
LEFT JOIN tb_project p ON p.project_id = m.project_id
LEFT JOIN sys_user u ON u.user_id = m.create_by
WHERE
p.project_type = 1
AND m.organization_id = #{organizationId}
AND i.organization_id = #{organizationId}
AND n.organization_id = #{organizationId}
AND p.organization_id = #{organizationId}
AND u.organization_id = #{organizationId}


        AND m.project_id IN

            #{projectId, jdbcType=BIGINT}




            AND m.project_id IN(
            SELECT project_id
            FROM tb_project
            WHERE organization_id = #{organizationId} AND project_type =1 AND project_id IN(
            SELECT DISTINCT project_id
            FROM tb_project_member
            WHERE user_id = #{userId}
            )
            )




    AND m.create_by IN

        #{createBy, jdbcType=BIGINT}



    AND m.category_id IN

        #{categoryId, jdbcType=BIGINT}



    AND i.indicator_id IN

        #{indicatorId, jdbcType=BIGINT}


GROUP BY m.project_id,m.create_by,n.indicator_id,m.category_id,m.organization_id
ORDER BY m.project_id ASC,m.create_by ASC,n.indicator_id ASC,m.category_id ASC

